        "633": { n: "Tube patency", t: "Full, according to pressure. Before starting injection, check the tube passability with water or compressed air from a compressor" },
        "634": { n: "Injection pressure", t: "≤ 80 atm. Do not let system pressure rise above 80 atm.; if necessary, inject with pauses, keeping the system pressure in the range of 20 to 40 atm" },
        "635": { n: "Injection resin consumption", t: "≤ 1,5 l/lin. m" },
