        "807": { n: "Quality masonry mortar (grade, workability, anti-freeze admixtures in winter)", t: "SP 82-101-98\nGrade must comply with the project. Adding water to ready mortar is not permitted.\nUse of anti-freeze admixtures.\nMortar data sheet." },
        "808": { n: "Vertical masonry joints", t: "Work Method Statement\nVertical joining of whole blocks is done without mortar, by fitting the tongue and groove of the laid blocks, with the joints pointed on both sides with mortar. A vertical joint is mortared only when joining:\n- two sawn blocks;\n- one sawn and one whole block;\n- abutment to the building frame;" },
        "809": { n: "Thickness of horizontal masonry joints", t: "Work Method Statement\nHorizontal joint thickness must be 10 (+/-2) mm" },
        "810": { n: "Thickness of the bottom levelling layer of the first course", t: "STO NOSTROY 2.9.136-2013, SP 70.13330.2012, Work Method Statement. For the first course, the thickness of the continuous leveling mortar joint may vary from 6 to 30 mm depending on the base surface." },
        "811": { n: "Uniform filling of joints with mortar", t: "SP 70.13330.2012 cl. 9.2.5, 9.2.6; Work Method Statement\nIncluding at the abutment of edge blocks to the walls over the full depth" },
        "812": { n: "Horizontality of masonry courses", t: "SP 70.13330.2012 Table 9.8; Work Method Statement, up to 15 mm per 10 m of wall length" },
        "813": { n: "Correctness of joint bonding pattern", t: "SP 70.13330.2012 cl. 9.2.1; Work Method Statement. Not less than 90 mm and not more than 410 mm" },
        "814": { n: "Wall thickness control", t: "SP 70.13330.2012 Table 9.8; Work Method Statement\nTolerance ±15 mm." },
        "815": { n: "Filling of gaps between the last masonry course and vertical building elements", t: "SP 70.13330.2012; Work Method Statement" },
        "816": { n: "Installation of lintels over openings", t: "SP 70.13330.2012; Work Method Statement\nFor an opening width up to 1 m — bearing left and right min. 100 mm. It is not recommended to have a vertical joint of partition blocks under the bearing part.\nFor an opening width up to 1.1 m — bearing left and right min. 100 mm, and along the entire length onto class AIII reinforcement anchored to the wall with a mandatory vertical mortar joint. The reinforcement is embedded into the RC wall to a recommended depth of 80 mm, with the other end of the bar run into the masonry not less than 250 mm,\nFor a width up to 1.6 m — clamp in the masonry as a cantilever with a bearing of not less than 400 mm (1/3), with bottom reinforcement by class A-III steel reinforcement, with the ends of the reinforcing bar run into the masonry structure not less than 250 mm." },
        "817": { n: "Weakening of masonry structures by grooves, chases, niches, openings", t: "SP 70.13330.2012 cl. 9.1.4; Work Method Statement" },
        "818": { n: "Masonry bonding", t: "SP 70.13330.2012 cl. 9.2.1; Work Method Statement\nBonding of masonry with a course offset of ½ of the unit length and not less than 1/3" },
        "819": { n: "Deviation of wall planes and corners from vertical", t: "SP 70.13330.2012 (Table 9.8); Work Method Statement\nTolerance not more than 10 mm over the full storey height" },
        "820": { n: "Irregularities on the vertical masonry surface.", t: "SP 70.13330.2012 (Table 9.8); Work Method Statement\nTolerance not more than 5 mm over the full storey height" },
        "821": { n: "SKT block laying free of soiling, mortar squeeze-out and hollows.", t: "SP 70.13330.2012; Work Method Statement" },
        "822": { n: "Deviation in pier width", t: "SP 70.13330.2012 (Table 9.8); Work Method Statement\nTolerance from 0 to «-15 mm»" },
        "823": { n: "Deviation in opening width", t: "SP 70.13330.2012 (Table 9.8); Work Method Statement\nTolerance from 0 to «+15 mm»" },
        "824": { n: "Offset from the design position of setting-out axes", t: "SP 70.13330.2012 (Table 9.8); Work Method Statement\nTolerance – 10 mm" },
        "825": { n: "Elevation deviation of the underside of lintel bearing surfaces", t: "SP 70.13330.2012 (Table 9.8); Work Method Statement\nTolerance «- 10 mm»" },
        "826": { n: "Deviation from horizontal of laid lintels", t: "SP 70.13330.2012; Work Method Statement\nTolerance - 10 mm" },
        "827": { n: "Deviation from symmetry (half the difference in bearing depth of the lintel ends)", t: "SP 70.13330.2012; Work Method Statement\nTolerance - 6 mm" },
        "828": { n: "Anchoring of SKT partitions to walls and floor slab", t: "Project, WEP, SP 15.13330.2020 (cl. 9.41, 9.44, Table 6.14), SP 70.13330.2012 (cl. 5.16.9)" },
        "829": { n: "Number of anchors and correctness of installation", t: "Quantity as per the project or WEP.\nFastening spacing every 3 blocks\nReinforcement diameter 6-8 mm\nBar length not less than 250 mm" },
