        "1721": { n: "Mesh reinforcement", t: "SP 163.1325800.2014 cl. 6.4.2.4 Fiberglass mesh 50 mm at joints, joint tape on all seams." },
        "1722": { n: "Layer thickness", t: "SP 163.1325800.2014 cl. 7.7.11 Tolerance: 1-2 mm (base), 0.3-0.5 mm (finish)" },
        "1723": { n: "Irregularities after sanding", t: "SP 163.1325800.2014 Annex K Tolerance: ≤0.5 mm/2 m" },
