        "2506": { n: "Setting-out of pile-field axes, benchmark elevations", t: "±10 mm (SP 126.13330 cl. 7.3)" },
        "2507": { n: "Preparation of the base for pile positioning (bedding)", t: "SP 45.13330.2017 (cl. 4.3, 4.7, 4.12); Compliance with the WEP, ensuring stability" },
        "2508": { n: "Pile appearance (no cracks, chips, or squeeze-out)", t: "No cracks, no exposed reinforcement, no concrete squeeze-out. (GOST 13015-2012 cl. 5.5)" },
        "2509": { n: "Geometric dimensions (length, cross-section)", t: "±10 mm in length; ±5 mm in cross-section (GOST 19804 cl. 6.13)" },
        "2510": { n: "Pile marking", t: "Internal company standard (GOST 23009-2016 governs the marking format, not its placement): at a distance of 500 mm from the end, or on the pile end" },
        "2511": { n: "Certificates and data sheets for piles", t: "(GOST 13015 cl. 6.9) (with mandatory indication of the concrete grade for frost resistance and water impermeability (if these parameters are specified in the order for the manufacture of\npiles)" },
        "2512": { n: "Pile position in plan before driving", t: "See Table 12.1 SP 45.13330.2017 (for piles up to 0.5 m: ±10 mm without a guide frame)" },
        "2513": { n: "Verticality of pile installation", t: "Deviation from vertical not more than 1,5% (or per the equipment data sheet). See Table 12.1 SP 45.13330.2017" },
        "2514": { n: "Driving depth / design set (refusal)", t: "Compliance with the project (design elevation or set value)" },
        "2515": { n: "Control of the jacking process", t: "SP 45.13330.2017 cl. 12.1.9, Annex E.3 (control by penetration depth and jacking force; force recorded every 10 cm over the last 50 cm). No sharp force spikes or skew, uniform movement — internal company standard" },
        "2516": { n: "Pile-head elevation after driving", t: "±3 cm (for a cast-in-place pile cap) - Table 12.1 SP 45.13330.2017" },
