        "2518": { n: "Coaxiality of sections", t: "No axis kinks, compliance with the working drawings (cl. 12.1.7 SP 45.13330.2017)" },
        "2519": { n: "Anti-corrosion treatment of the weld", t: "Compliance with the working drawings and WEP (cl. 9.3.11 SP 28.13330)" },
        "2520": { n: "Static jacking-load tests", t: "Test programme agreed with the Client and the General Designer" },
