        "4201": { n: "Lines of intersecting planes from the vertical or design slope over the entire height of the structure:\n- walls supporting monolithic coverings and floors", t: "≤15 mm\nSP 70.13330.2012 Table 5.12" },
        "4202": { n: "- local unevenness of the concrete surface when checked with a two-meter straightedge, except bearing surfaces", t: "≤5 mm\nSP 70.13330.2012 Table 5.12" },
        "4203": { n: "- horizontal planes over the entire length of the section being checked:\n- element length:", t: "20 mm\n±20 mm\nSP 70.13330.2012 Table 5.12" },
        "4204": { n: "Dimensions of window, door, and other openings", t: "±12 mm\nSP 70.13330.2012 Table 5.12" },
        "4205": { n: "Exposed reinforcement", t: "Not permitted\nSP 70.13330.2012 cl.5.18.4, Annex X" },
        "4206": { n: "Voids, concrete chips", t: "≤15 mm and ≤5 mm deep, edge chips ≤10 mm. SP 70.13330.2012 cl.5.18.4" },
        "4207": { n: "Areas of unconsolidated concrete", t: "Not permitted\nSP 70.13330.2012 cl.5.18.4, Annex X" },
        "4208": { n: "Compliance with concrete surface class A6", t: "SP 70.13330.2012 Annex X: voids larger than 15 mm in diameter, deeper than 5 mm, and edge chips 10 mm deep with total length exceeding 100 mm per 1 m of edge, are not permitted" },
        "4209": { n: "Height deviation of the top of the ventilation opening", t: "±8 mm\nGOST 17079-2021 Table 1" },
        "4210": { n: "Cracks wider than 0,2 mm on the surfaces of ventilation blocks, except shrinkage and other local technological cracks", t: "GOST 17079-2021 cl.4.4.3" },
        "4211": { n: "Exposed reinforcement", t: "GOST 13015-2012 cl.5.5.3" },
        "4212": { n: "Grease and rust stains on block surfaces", t: "GOST 13015-2012 cl.5.5.5" },
