        "4232": { n: "Deviation from symmetry (half the difference in bearing depth of the lintel ends)", t: "SP 70.13330.2012; Work Method Statement\nTolerance - 6 mm" },
        "4233": { n: "Wall", t: "\"SP 71.13330.2017\" Table 7.4. Maximum deviation from vertical not more than 3 mm per 1 m, but not more than 10 mm over the full room height" },
        "4234": { n: "Wall/ceiling", t: "\"SP 71.13330.2017\" Table 7.4. Maximum deviation from horizontal not more than 3 mm per 1 m" },
