        "4238": { n: "Wall/ceiling", t: "\"SP 71.13330.2017\" Table 7.4.\nMaximum deviation from horizontal not more than 3 mm per 1 m" },
        "4239": { n: "Window/door reveals, pilasters, columns, etc.", t: "\"SP 71.13330.2017\" Table 7.4.\nDeviation from vertical and horizontal over an area of 4m2 not more than 4 mm per 1 m, but not more than 10 mm over the whole element" },
        "4240": { n: "Reveal width", t: "\"SP 71.13330.2017 Table 7.4.\nDeviation from design width not more than 3 mm" },
